public sealed class ExecutableEditorForm:AppForm{
static readonly Color Bg=Color.FromArgb(15,17,21),Surface=Color.FromArgb(24,27,33),Surface2=Color.FromArgb(31,35,43),Border=Color.FromArgb(51,57,68),TextColor=Color.FromArgb(235,237,241),Muted=Color.FromArgb(154,162,176),Accent=Color.FromArgb(190,55,57);
