public ExecutableEditorForm(string? suggestedElf,string? suggestedIso=null,bool createIsoBackup=true){this.createIsoBackup=createIsoBackup;Text="Editor de executável • Resident Evil 4 PS2";BackColor=Bg;ForeColor=TextColor;Font=new("Segoe UI",9F);MinimumSize=new(940,650);Size=new(1120,760);StartPosition=FormStartPosition.CenterParent;BuildUi();FormClosing+=ConfirmClose;if(!string.IsNullOrWhiteSpace(suggestedIso)&&File.Exists(suggestedIso))Shown+=(_,_)=>LoadIso(suggestedIso);else if(!string.IsNullOrWhiteSpace(suggestedElf)&&File.Exists(suggestedElf))Shown+=(_,_)=>LoadElf(suggestedElf);}
void BuildUi(){var head=new Panel{Dock=DockStyle.Top,Height=104,BackColor=Surface,Padding=new(24,18,24,12)};head.Controls.Add(new Label{Text="EDITOR DE EXECUTÁVEL",Dock=DockStyle.Top,Height=30,ForeColor=TextColor,Font=new("Segoe UI Semibold",15F)});fileLabel.Text="Nenhum ELF carregado";fileLabel.Dock=DockStyle.Bottom;fileLabel.Height=28;fileLabel.ForeColor=Muted;fileLabel.AutoEllipsis=true;head.Controls.Add(fileLabel);
