void LoadElf(string path){try{doc=Ps2ExecutableDocument.Open(path);BuildTabs();fileLabel.Text=$"{doc.ProductCode}   •   {Path.GetFileName(path)}   •   {new FileInfo(path).Length:N0} bytes";status.Text="Valores carregados. Campos alterados são destacados.";save.Enabled=revert.Enabled=false;}catch(Exception ex){MessageBox.Show(ex.Message,"Executável incompatível",MessageBoxButtons.OK,MessageBoxIcon.Warning);}}
