void BuildTabs(){loading=true;try{tabs.TabPages.Clear();grids.Clear();Capacity();Floats("PODER DE FOGO",Ps2ExecutableMap.Damage(doc!.Region),7,false);Floats("RECARGA",Ps2ExecutableMap.Reload(doc.Region),3,true);Floats("DISPARO",Ps2ExecutableMap.Firing(doc.Region),5,true);Upgrades();Limits();Tweaks();EnemyHud();}finally{loading=false;}}
DataGridView Grid(string key){var g=new DataGridView{Dock=DockStyle.Fill,BackgroundColor=Bg,BorderStyle=BorderStyle.None,GridColor=Border,RowHeadersVisible=false,AllowUserToAddRows=false,AllowUserToDeleteRows=false,AutoSizeColumnsMode=DataGridViewAutoSizeColumnsMode.Fill,SelectionMode=DataGridViewSelectionMode.CellSelect,EnableHeadersVisualStyles=false};g.ColumnHeadersDefaultCellStyle=new(){BackColor=Surface2,ForeColor=TextColor,SelectionBackColor=Surface2,Font=new("Segoe UI Semibold",9F),Padding=new(4)};g.DefaultCellStyle=new(){BackColor=Surface,ForeColor=TextColor,SelectionBackColor=Color.FromArgb(92,42,45),SelectionForeColor=Color.White,Padding=new(4)};g.AlternatingRowsDefaultCellStyle.BackColor=Color.FromArgb(27,30,37);g.RowTemplate.Height=31;g.CellValueChanged+=(_,e)=>{if(!loading&&e.RowIndex>=0)Dirty(g.Rows[e.RowIndex]);};grids[key]=g;var p=new TabPage(key){BackColor=Bg,Padding=new(12)};p.Controls.Add(g);tabs.TabPages.Add(p);return g;}
void Capacity(){var g=Grid("CAPACIDADE");Col(g,"Arma",true,190);Cols(g,"Nível ",6);Num(g,"Exclusivo");foreach(var x in Ps2ExecutableMap.Capacity(doc!.Region)){int r=g.Rows.Add(x.Name);g.Rows[r].Tag=x.Offset;for(int i=0;i<7;i++)g.Rows[r].Cells[i+1].Value=doc.U16(x.Offset+8+i*2);}}
void Floats(string title,IReadOnlyList<(string Name,int Offset)> map,int count,bool normalized){var g=Grid(title);Col(g,"Arma",true,190);Cols(g,"Nível ",count);foreach(var x in map){int r=g.Rows.Add(x.Name);g.Rows[r].Tag=x.Offset;for(int i=0;i<count;i++){decimal v=(decimal)doc!.F32(x.Offset+i*4);if(normalized)v/=30m;g.Rows[r].Cells[i+1].Value=Math.Round(v,2);}}}
void Upgrades(){var g=Grid("UPGRADES");Col(g,"Arma",true,190);foreach(string s in new[]{"ID","Poder","Disparo","Recarga","Capacidade"})Num(g,s);foreach(var x in Ps2ExecutableMap.Upgrades(doc!.Region)){int r=g.Rows.Add(x.Name,doc.U16(x.Offset),doc.U8(x.Offset+2),doc.U8(x.Offset+3),doc.U8(x.Offset+4),doc.U8(x.Offset+5));g.Rows[r].Tag=x.Offset;}}
void Limits(){var g=Grid("LIMITES GERAIS");Col(g,"Categoria",true,280);Num(g,"Limite");foreach(var x in Ps2ExecutableMap.Limits(doc!.Region)){int r=g.Rows.Add(x.Name,doc.U16(x.Offset));g.Rows[r].Tag=x.Offset;}}
void Tweaks(){speedPatchState=null;speedPatchApply=null;speedPatchRemove=null;speedMultiplier=null;introPatchState=null;introPatchApply=null;introPatchRemove=null;if(doc?.Region!=ExecutableRegion.DebugSlps)return;var page=new TabPage("AJUSTES"){BackColor=Bg,Padding=new(16)};var stack=new TableLayoutPanel{Dock=DockStyle.Top,AutoSize=true,AutoSizeMode=AutoSizeMode.GrowAndShrink,ColumnCount=1,RowCount=2,BackColor=Bg,Margin=Padding.Empty,Padding=Padding.Empty};stack.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,100F));var card=new Panel{Dock=DockStyle.Top,Height=214,BackColor=Surface2,Margin=new Padding(0,0,0,12)};card.Controls.Add(new Label{Text="VELOCIDADE DO JOGADOR",Left=18,Top=15,Width=520,Height=25,ForeColor=TextColor,Font=new("Segoe UI Semibold",11F)});card.Controls.Add(new Label{Text="Altera a velocidade da animação e do deslocamento de Leon, inclusive após trocar de arma ou animação.",Left=18,Top=45,Width=820,Height=34,ForeColor=Muted});card.Controls.Add(new Label{Text="MULTIPLICADOR",Left=18,Top=86,Width=150,Height=20,ForeColor=Muted,Font=new("Segoe UI Semibold",8F)});speedMultiplier=new ComboBox{Left=18,Top=108,Width=160,Height=30,DropDownStyle=ComboBoxStyle.DropDownList,BackColor=Surface,ForeColor=TextColor,FlatStyle=FlatStyle.Flat};foreach(decimal value in DebugPlayerSpeedPatch.SupportedMultipliers)speedMultiplier.Items.Add($"{value:0.00}×");speedMultiplier.SelectedIndex=3;card.Controls.Add(speedMultiplier);speedPatchState=new Label{Left=195,Top=107,Width=640,Height=31,TextAlign=ContentAlignment.MiddleLeft,Font=new("Segoe UI Semibold",9F)};card.Controls.Add(speedPatchState);speedPatchApply=new Button{Left=18,Top=158};Style(speedPatchApply,"APLICAR VELOCIDADE",Accent,190);speedPatchApply.Click+=(_,_)=>ChangeSpeedPatch();card.Controls.Add(speedPatchApply);speedPatchRemove=new Button{Left=220,Top=158};Style(speedPatchRemove,"RESTAURAR ORIGINAL",Surface,180);speedPatchRemove.Click+=(_,_)=>RemoveSpeedPatch();card.Controls.Add(speedPatchRemove);var introCard=new Panel{Dock=DockStyle.Top,Height=174,BackColor=Surface2,Margin=new Padding(0,0,0,12)};introCard.Controls.Add(new Label{Text="PULAR LOGOS INICIAIS",Left=18,Top=15,Width=520,Height=25,ForeColor=TextColor,Font=new("Segoe UI Semibold",11F)});introCard.Controls.Add(new Label{Text="Cancela as quatro telas de abertura com a limpeza normal do jogo e segue para o menu principal.",Left=18,Top=45,Width=820,Height=30,ForeColor=Muted});introPatchState=new Label{Left=18,Top=80,Width=800,Height=25,Font=new("Segoe UI Semibold",9F)};introCard.Controls.Add(introPatchState);introPatchApply=new Button{Left=18,Top=121};Style(introPatchApply,"PULAR LOGOS",Accent,190);introPatchApply.Click+=(_,_)=>ChangeIntroPatch(true);introCard.Controls.Add(introPatchApply);introPatchRemove=new Button{Left=220,Top=121};Style(introPatchRemove,"RESTAURAR ORIGINAL",Surface,180);introPatchRemove.Click+=(_,_)=>ChangeIntroPatch(false);introCard.Controls.Add(introPatchRemove);stack.Controls.Add(card,0,0);stack.Controls.Add(introCard,0,1);page.Controls.Add(stack);tabs.TabPages.Add(page);RefreshSpeedPatchUi();RefreshIntroPatchUi();}
void ChangeSpeedPatch(){if(doc==null||speedMultiplier==null)return;try{float multiplier=(float)DebugPlayerSpeedPatch.SupportedMultipliers[speedMultiplier.SelectedIndex];DebugPlayerSpeedPatch.Apply(doc,multiplier);save.Enabled=revert.Enabled=true;status.Text=$"Velocidade {multiplier:0.00}× preparada. Clique em SALVAR ALTERAÇÕES para gravar.";RefreshSpeedPatchUi();}catch(Exception ex){MessageBox.Show(ex.Message,"Velocidade do jogador",MessageBoxButtons.OK,MessageBoxIcon.Warning);RefreshSpeedPatchUi();}}
void RemoveSpeedPatch(){if(doc==null)return;try{DebugPlayerSpeedPatch.Remove(doc);save.Enabled=revert.Enabled=true;status.Text="Restauração da velocidade preparada. Clique em SALVAR ALTERAÇÕES para gravar.";RefreshSpeedPatchUi();}catch(Exception ex){MessageBox.Show(ex.Message,"Velocidade do jogador",MessageBoxButtons.OK,MessageBoxIcon.Warning);RefreshSpeedPatchUi();}}
void RefreshSpeedPatchUi(){if(doc==null||speedPatchState==null)return;var state=DebugPlayerSpeedPatch.GetState(doc);float? multiplier=DebugPlayerSpeedPatch.GetMultiplier(doc);speedPatchState.Text=state switch{DebugPlayerSpeedPatchState.Ready=>"ORIGINAL  •  velocidade padrão do jogo",DebugPlayerSpeedPatchState.Applied=>$"PATCH APLICADO  •  velocidade {multiplier:0.00}×",_=>"ESTADO NÃO RECONHECIDO  •  os bytes desta área foram modificados"};speedPatchState.ForeColor=state switch{DebugPlayerSpeedPatchState.Ready=>Color.FromArgb(112,205,155),DebugPlayerSpeedPatchState.Applied=>Color.FromArgb(105,190,255),_=>Color.FromArgb(255,177,92)};if(multiplier.HasValue&&speedMultiplier!=null){int index=Array.FindIndex(DebugPlayerSpeedPatch.SupportedMultipliers,x=>Math.Abs((float)x-multiplier.Value)<0.001f);if(index>=0)speedMultiplier.SelectedIndex=index;}if(speedPatchApply!=null)speedPatchApply.Enabled=state!=DebugPlayerSpeedPatchState.Incompatible;if(speedPatchRemove!=null)speedPatchRemove.Enabled=state==DebugPlayerSpeedPatchState.Applied;}
void ChangeIntroPatch(bool apply){if(doc==null)return;try{if(apply)DebugSkipIntroLogosPatch.Apply(doc);else DebugSkipIntroLogosPatch.Remove(doc);save.Enabled=revert.Enabled=true;status.Text=apply?"Pulo dos logos preparado. Clique em SALVAR ALTERAÇÕES para gravar.":"Restauração dos logos preparada. Clique em SALVAR ALTERAÇÕES para gravar.";RefreshIntroPatchUi();}catch(Exception ex){MessageBox.Show(ex.Message,"Logos iniciais",MessageBoxButtons.OK,MessageBoxIcon.Warning);RefreshIntroPatchUi();}}
void RefreshIntroPatchUi(){if(doc==null||introPatchState==null)return;var state=DebugSkipIntroLogosPatch.GetState(doc);introPatchState.Text=state switch{DebugSkipIntroLogosPatchState.Ready=>"ORIGINAL  •  quatro telas de abertura ativas",DebugSkipIntroLogosPatchState.Applied=>"PATCH APLICADO  •  abertura segue direto ao menu",_=>"ESTADO NÃO RECONHECIDO  •  os bytes desta área foram modificados"};introPatchState.ForeColor=state switch{DebugSkipIntroLogosPatchState.Ready=>Color.FromArgb(112,205,155),DebugSkipIntroLogosPatchState.Applied=>Color.FromArgb(105,190,255),_=>Color.FromArgb(255,177,92)};if(introPatchApply!=null)introPatchApply.Enabled=state==DebugSkipIntroLogosPatchState.Ready;if(introPatchRemove!=null)introPatchRemove.Enabled=state==DebugSkipIntroLogosPatchState.Applied;}
void EnemyHud(){hpPatchState=null;hpPatchApply=null;hpPatchRemove=null;if(doc?.Region!=ExecutableRegion.DebugSlps)return;var page=new TabPage("HUD DE INIMIGOS"){BackColor=Bg,Padding=new(22)};var card=new Panel{Dock=DockStyle.Top,Height=255,BackColor=Surface2,Padding=new(22)};card.Controls.Add(new Label{Text="BARRA DE VIDA DOS INIMIGOS",Left=22,Top=20,Width=520,Height=28,ForeColor=TextColor,Font=new("Segoe UI Semibold",12F)});card.Controls.Add(new Label{Text="Injeta no SLPS debug uma barra centralizada sobre cada inimigo, orientada para a câmera e posicionada pela caixa do modelo. O fundo indica o HP máximo e o preenchimento verde diminui com o dano.",Left=22,Top=58,Width=760,Height=58,ForeColor=Muted});hpPatchState=new Label{Left=22,Top=128,Width=760,Height=28,Font=new("Segoe UI Semibold",9F)};card.Controls.Add(hpPatchState);hpPatchApply=new Button{Left=22,Top=176};Style(hpPatchApply,"INJETAR BARRA DE HP",Accent,190);hpPatchApply.Click+=(_,_)=>ChangeHpPatch(true);card.Controls.Add(hpPatchApply);hpPatchRemove=new Button{Left=224,Top=176};Style(hpPatchRemove,"RESTAURAR ORIGINAL",Surface,180);hpPatchRemove.Click+=(_,_)=>ChangeHpPatch(false);card.Controls.Add(hpPatchRemove);page.Controls.Add(card);tabs.TabPages.Add(page);RefreshHpPatchUi();}
void ChangeHpPatch(bool apply){if(doc==null)return;try{if(apply)DebugEnemyHpBarPatch.Apply(doc);else DebugEnemyHpBarPatch.Remove(doc);save.Enabled=revert.Enabled=true;status.Text=apply?"Barra de HP preparada. Clique em SALVAR ALTERAÇÕES para gravar.":"Restauração preparada. Clique em SALVAR ALTERAÇÕES para gravar.";RefreshHpPatchUi();}catch(Exception ex){MessageBox.Show(ex.Message,"HUD de inimigos",MessageBoxButtons.OK,MessageBoxIcon.Warning);RefreshHpPatchUi();}}
