static void Col(DataGridView g,string t,bool ro,int w)=>g.Columns.Add(new DataGridViewTextBoxColumn{HeaderText=t,ReadOnly=ro,FillWeight=w});static void Cols(DataGridView g,string p,int n){for(int i=1;i<=n;i++)Num(g,p+i);}static void Num(DataGridView g,string t)=>g.Columns.Add(new DataGridViewTextBoxColumn{HeaderText=t,ValueType=typeof(decimal),FillWeight=75});
void Dirty(DataGridViewRow r){r.DefaultCellStyle.ForeColor=Color.FromArgb(255,210,112);save.Enabled=revert.Enabled=true;status.Text="Existem alterações ainda não salvas.";}
void Save(){if(doc==null)return;try{CommitCapacity();CommitFloat("PODER DE FOGO",false);CommitFloat("RECARGA",true);CommitFloat("DISPARO",true);CommitUpgrades();CommitLimits();doc.Save(createIsoBackup);foreach(var g in grids.Values)foreach(DataGridViewRow r in g.Rows)r.DefaultCellStyle.ForeColor=TextColor;save.Enabled=revert.Enabled=false;string backup=Path.GetFileName(doc.IsIso?doc.IsoPath:doc.FilePath)+".bak";status.Text=doc.IsIso&&!createIsoBackup?"Salvo diretamente na ISO • backup desativado nas Configurações":$"Salvo com segurança. Backup: {backup}";RefreshSpeedPatchUi();RefreshIntroPatchUi();RefreshHpPatchUi();}catch(Exception ex){MessageBox.Show(ex.Message,"Não foi possível salvar",MessageBoxButtons.OK,MessageBoxIcon.Error);}}
void CommitCapacity(){foreach(DataGridViewRow r in grids["CAPACIDADE"].Rows){int o=(int)r.Tag!;for(int i=0;i<7;i++)doc!.U16(o+8+i*2,Val(r,i+1));}}
void CommitFloat(string key,bool norm){foreach(DataGridViewRow r in grids[key].Rows){int o=(int)r.Tag!;for(int i=1;i<r.Cells.Count;i++)doc!.F32(o+(i-1)*4,Val(r,i)*(norm?30:1));}}
void CommitUpgrades(){foreach(DataGridViewRow r in grids["UPGRADES"].Rows){int o=(int)r.Tag!;doc!.U16(o,Val(r,1));for(int i=2;i<=5;i++)doc.U8(o+i,Val(r,i));}}
void CommitLimits(){foreach(DataGridViewRow r in grids["LIMITES GERAIS"].Rows)doc!.U16((int)r.Tag!,Val(r,1));}
static decimal Val(DataGridViewRow r,int c){if(!decimal.TryParse(Convert.ToString(r.Cells[c].Value),out decimal v))throw new InvalidDataException($"Valor inválido em {r.Cells[0].Value}, coluna {r.DataGridView?.Columns[c].HeaderText}.");return v;}
void Revert(){if(doc==null)return;doc.Revert();if(doc.IsIso)LoadIso(doc.IsoPath!);else LoadElf(doc.FilePath);}
void ConfirmClose(object? sender,FormClosingEventArgs e){if(save.Enabled&&MessageBox.Show("Descartar as alterações não salvas?","Editor de executável",MessageBoxButtons.YesNo,MessageBoxIcon.Question)!=DialogResult.Yes)e.Cancel=true;}static void Style(Button b,string t,Color c,int w){b.Text=t;b.Width=w;b.Height=34;b.BackColor=c;b.ForeColor=Color.White;b.FlatStyle=FlatStyle.Flat;b.FlatAppearance.BorderSize=0;b.Font=new("Segoe UI Semibold",8.5F);b.Cursor=Cursors.Hand;}
void DrawTab(object? s,DrawItemEventArgs e){using var b=new SolidBrush(e.Index==tabs.SelectedIndex?Accent:Surface2);e.Graphics.FillRectangle(b,e.Bounds);TextRenderer.DrawText(e.Graphics,tabs.TabPages[e.Index].Text,tabs.Font,e.Bounds,TextColor,TextFormatFlags.HorizontalCenter|TextFormatFlags.VerticalCenter);}
